-- Access contract 2026-10-15. Tenant ownership, client grants and RLS.
-- Do not edit this file after it has been applied. Ship a later migration.

do $$
begin
  if to_regprocedure('auth.uid()') is null or to_regprocedure('auth.jwt()') is null then
    raise exception 'auth.uid() and auth.jwt() are required (Supabase Auth)';
  end if;
  begin
    perform auth.uid();
    perform auth.jwt();
  exception
    when insufficient_privilege then
      raise exception 'migration login cannot execute auth.uid() or auth.jwt()';
  end;
end $$;

do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then
    create role anon nologin nobypassrls nosuperuser;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    create role authenticated nologin nobypassrls nosuperuser;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'app_request') then
    create role app_request nologin nobypassrls nosuperuser;
  end if;
end $$;

create schema if not exists app;
revoke all on schema app from public, anon;
grant usage on schema app to app_request, authenticated;

-- The migration login can already execute the platform identity functions.
-- These security-definer wrappers keep that ability with the login that
-- applied the migration. app_request is not granted schema auth.
create function app.auth_uid()
returns uuid
language sql
stable
security definer
set search_path = auth, pg_catalog
as $$
  select auth.uid()
$$;

create function app.auth_jwt()
returns jsonb
language sql
stable
security definer
set search_path = auth, pg_catalog
as $$
  select auth.jwt()
$$;

revoke all on function app.auth_uid() from public, anon, authenticated;
revoke all on function app.auth_jwt() from public, anon, authenticated;
grant execute on function app.auth_uid() to app_request;
grant execute on function app.auth_jwt() to app_request;

create or replace function app.permissions_allowed(perms text[])
returns boolean
language sql
immutable
as $$
  select perms is not null
    and perms <@ array['business.read', 'business.onboard', 'reports.read']::text[]
$$;

create table app.businesses (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null,
  display_name text not null,
  created_at timestamptz not null default now(),
  constraint businesses_one_owner unique (owner_user_id),
  constraint businesses_display_name_length check (
    char_length(display_name) between 1 and 120
  )
);

create table app.client_grants (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null,
  business_id uuid references app.businesses (id),
  oauth_client_id text not null,
  permissions text[] not null,
  granted_at timestamptz not null default now(),
  revoked_at timestamptz,
  constraint client_grants_owner_client unique (owner_user_id, oauth_client_id),
  constraint client_grants_permissions_known check (app.permissions_allowed(permissions))
);

create table app.oauth_consents (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null,
  oauth_client_id text not null,
  authorization_id text,
  decision text not null,
  scopes text[] not null,
  permissions text[] not null,
  decided_at timestamptz not null default now(),
  constraint oauth_consents_decision check (decision in ('approved', 'denied')),
  constraint oauth_consents_permissions_known check (app.permissions_allowed(permissions))
);

create table app.business_creation_keys (
  owner_user_id uuid not null,
  idempotency_key text not null,
  business_id uuid not null references app.businesses (id),
  created_at timestamptz not null default now(),
  primary key (owner_user_id, idempotency_key)
);

create table app.access_audit (
  id uuid primary key default gen_random_uuid(),
  occurred_at timestamptz not null default now(),
  actor_user_id uuid,
  business_id uuid,
  oauth_client_id text,
  action text not null,
  outcome text not null,
  detail jsonb not null default '{}'::jsonb
);

alter table app.businesses enable row level security;
alter table app.businesses force row level security;
alter table app.client_grants enable row level security;
alter table app.client_grants force row level security;
alter table app.oauth_consents enable row level security;
alter table app.oauth_consents force row level security;
alter table app.business_creation_keys enable row level security;
alter table app.business_creation_keys force row level security;
alter table app.access_audit enable row level security;
alter table app.access_audit force row level security;

revoke all on all tables in schema app from public, anon;
grant select, insert, update, delete on all tables in schema app to app_request, authenticated;

create or replace function app.reject_owner_change()
returns trigger
language plpgsql
as $$
begin
  if new.owner_user_id is distinct from old.owner_user_id then
    raise exception 'owner_immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger businesses_owner_immutable
  before update on app.businesses
  for each row execute function app.reject_owner_change();

create policy businesses_owner on app.businesses
  as permissive for all
  to app_request, authenticated
  using (owner_user_id = app.auth_uid())
  with check (owner_user_id = app.auth_uid());

create policy businesses_delegated_select on app.businesses
  as restrictive for select
  to app_request, authenticated
  using (
    (app.auth_jwt() ->> 'client_id') is null
    or exists (
      select 1
      from app.client_grants g
      where g.owner_user_id = app.auth_uid()
        and g.oauth_client_id = (app.auth_jwt() ->> 'client_id')
        and g.revoked_at is null
        and (
          g.business_id is null
          or g.business_id = businesses.id
        )
        and g.permissions && array['business.read', 'reports.read']::text[]
    )
  );

create policy businesses_delegated_insert on app.businesses
  as restrictive for insert
  to app_request, authenticated
  with check (
    (app.auth_jwt() ->> 'client_id') is null
    or exists (
      select 1
      from app.client_grants g
      where g.owner_user_id = app.auth_uid()
        and g.oauth_client_id = (app.auth_jwt() ->> 'client_id')
        and g.revoked_at is null
        and 'business.onboard' = any (g.permissions)
    )
  );

create policy businesses_owner_update on app.businesses
  as restrictive for update
  to app_request, authenticated
  using ((app.auth_jwt() ->> 'client_id') is null)
  with check (
    (app.auth_jwt() ->> 'client_id') is null
    and owner_user_id = app.auth_uid()
  );

create policy businesses_owner_delete on app.businesses
  as restrictive for delete
  to app_request, authenticated
  using ((app.auth_jwt() ->> 'client_id') is null);

create policy grants_select on app.client_grants
  as permissive for select
  to app_request, authenticated
  using (owner_user_id = app.auth_uid());

create policy grants_write on app.client_grants
  as permissive for insert
  to app_request, authenticated
  with check (
    owner_user_id = app.auth_uid()
    and (app.auth_jwt() ->> 'client_id') is null
  );

create policy grants_update on app.client_grants
  as permissive for update
  to app_request, authenticated
  using (
    owner_user_id = app.auth_uid()
    and (app.auth_jwt() ->> 'client_id') is null
  )
  with check (
    owner_user_id = app.auth_uid()
    and (app.auth_jwt() ->> 'client_id') is null
  );

create policy consents_owner on app.oauth_consents
  as permissive for all
  to app_request, authenticated
  using (
    owner_user_id = app.auth_uid()
    and (app.auth_jwt() ->> 'client_id') is null
  )
  with check (
    owner_user_id = app.auth_uid()
    and (app.auth_jwt() ->> 'client_id') is null
  );

create policy creation_keys_owner on app.business_creation_keys
  as permissive for all
  to app_request, authenticated
  using (owner_user_id = app.auth_uid())
  with check (owner_user_id = app.auth_uid());

create policy audit_insert on app.access_audit
  as permissive for insert
  to app_request, authenticated
  with check (actor_user_id = app.auth_uid());

create policy audit_select on app.access_audit
  as permissive for select
  to app_request, authenticated
  using (
    actor_user_id = app.auth_uid()
    and (app.auth_jwt() ->> 'client_id') is null
  );

create or replace function app.create_business(
  p_display_name text,
  p_idempotency_key text
)
returns table (
  id uuid,
  display_name text,
  owner_user_id uuid,
  created boolean
)
language plpgsql
security invoker
set search_path = app, pg_temp
as $$
declare
  existing_id uuid;
  existing_name text;
  existing_owner uuid;
  new_row app.businesses%rowtype;
begin
  if p_display_name is null
    or char_length(btrim(p_display_name)) < 1
    or char_length(btrim(p_display_name)) > 120
    or btrim(p_display_name) ~ '[[:cntrl:]]' then
    raise exception 'invalid_name' using errcode = 'P0001';
  end if;
  if p_idempotency_key is null
    or char_length(p_idempotency_key) < 1
    or char_length(p_idempotency_key) > 200 then
    raise exception 'invalid_idempotency_key' using errcode = 'P0001';
  end if;
  if app.auth_uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  if (app.auth_jwt() ->> 'client_id') is not null
    and not exists (
      select 1
      from app.client_grants g
      where g.owner_user_id = app.auth_uid()
        and g.oauth_client_id = (app.auth_jwt() ->> 'client_id')
        and g.revoked_at is null
        and 'business.onboard' = any (g.permissions)
    ) then
    raise exception 'permission_denied' using errcode = '42501';
  end if;

  select k.business_id
  into existing_id
  from app.business_creation_keys k
  where k.owner_user_id = app.auth_uid()
    and k.idempotency_key = p_idempotency_key;
  if existing_id is not null then
    return query
    select b.id, b.display_name, b.owner_user_id, false
    from app.businesses b
    where b.id = existing_id;
    return;
  end if;

  select b.id, b.display_name, b.owner_user_id
  into existing_id, existing_name, existing_owner
  from app.businesses b
  where b.owner_user_id = app.auth_uid();
  if existing_id is not null then
    insert into app.business_creation_keys (owner_user_id, idempotency_key, business_id)
    values (app.auth_uid(), p_idempotency_key, existing_id)
    on conflict do nothing;
    return query select existing_id, existing_name, existing_owner, false;
    return;
  end if;

  insert into app.businesses (owner_user_id, display_name)
  values (app.auth_uid(), btrim(p_display_name))
  returning * into new_row;

  insert into app.business_creation_keys (owner_user_id, idempotency_key, business_id)
  values (app.auth_uid(), p_idempotency_key, new_row.id);

  insert into app.access_audit (
    actor_user_id, business_id, oauth_client_id, action, outcome, detail
  )
  values (
    app.auth_uid(),
    new_row.id,
    app.auth_jwt() ->> 'client_id',
    'create_business',
    'created',
    '{}'::jsonb
  );

  return query
  select new_row.id, new_row.display_name, new_row.owner_user_id, true;
exception
  when unique_violation then
    select b.id, b.display_name, b.owner_user_id
    into existing_id, existing_name, existing_owner
    from app.businesses b
    where b.owner_user_id = app.auth_uid();
    if existing_id is null then
      raise;
    end if;
    return query select existing_id, existing_name, existing_owner, false;
end;
$$;

create or replace function app.record_client_consent(
  p_oauth_client_id text,
  p_permissions text[],
  p_scopes text[],
  p_authorization_id text,
  p_decision text
)
returns void
language plpgsql
security invoker
set search_path = app, pg_temp
as $$
declare
  recent integer;
begin
  if app.auth_uid() is null or (app.auth_jwt() ->> 'client_id') is not null then
    raise exception 'permission_denied' using errcode = '42501';
  end if;
  if p_decision not in ('approved', 'denied') then
    raise exception 'invalid_decision' using errcode = 'P0001';
  end if;
  if p_oauth_client_id is null or char_length(p_oauth_client_id) < 1 then
    raise exception 'invalid_client' using errcode = 'P0001';
  end if;
  if not app.permissions_allowed(p_permissions) then
    raise exception 'invalid_permissions' using errcode = 'P0001';
  end if;
  select count(*)
  into recent
  from app.oauth_consents c
  where c.owner_user_id = app.auth_uid()
    and c.decided_at > now() - interval '1 hour';
  if recent >= 20 then
    raise exception 'rate_limited' using errcode = 'P0001';
  end if;

  insert into app.oauth_consents (
    owner_user_id,
    oauth_client_id,
    authorization_id,
    decision,
    scopes,
    permissions
  )
  values (
    app.auth_uid(),
    p_oauth_client_id,
    p_authorization_id,
    p_decision,
    coalesce(p_scopes, array[]::text[]),
    p_permissions
  );

  if p_decision = 'approved' then
    insert into app.client_grants (
      owner_user_id,
      business_id,
      oauth_client_id,
      permissions
    )
    values (
      app.auth_uid(),
      (select b.id from app.businesses b where b.owner_user_id = app.auth_uid()),
      p_oauth_client_id,
      p_permissions
    )
    on conflict (owner_user_id, oauth_client_id) do update
    set permissions = excluded.permissions,
        revoked_at = null,
        granted_at = now(),
        business_id = coalesce(client_grants.business_id, excluded.business_id);
  end if;
end;
$$;

create or replace function app.revoke_client_grant(p_oauth_client_id text)
returns boolean
language plpgsql
security invoker
set search_path = app, pg_temp
as $$
declare
  updated integer;
begin
  if app.auth_uid() is null or (app.auth_jwt() ->> 'client_id') is not null then
    raise exception 'permission_denied' using errcode = '42501';
  end if;
  update app.client_grants
  set revoked_at = now()
  where owner_user_id = app.auth_uid()
    and oauth_client_id = p_oauth_client_id
    and revoked_at is null;
  get diagnostics updated = row_count;
  insert into app.access_audit (
    actor_user_id, oauth_client_id, action, outcome, detail
  )
  values (
    app.auth_uid(),
    p_oauth_client_id,
    'revoke_grant',
    case when updated > 0 then 'revoked' else 'absent' end,
    '{}'::jsonb
  );
  return updated > 0;
end;
$$;

revoke all on function app.create_business(text, text) from public, anon;
revoke all on function app.record_client_consent(text, text[], text[], text, text) from public, anon;
revoke all on function app.revoke_client_grant(text) from public, anon;
grant execute on function app.create_business(text, text) to app_request, authenticated;
grant execute on function app.record_client_consent(text, text[], text[], text, text) to app_request, authenticated;
grant execute on function app.revoke_client_grant(text) to app_request, authenticated;
